<?php require 'config.php'; if(!isset($_SESSION['user'])){header('Location:login.php');exit;} $id=(int)($_GET['id']??0); $st=$pdo->prepare('SELECT image FROM projects WHERE id=?'); $st->execute([$id]); $p=$st->fetch(); if($p){ if(!empty($p['image']) && file_exists(__DIR__.'/uploads/'.$p['image'])) @unlink(__DIR__.'/uploads/'.$p['image']); $pdo->prepare('DELETE FROM projects WHERE id=?')->execute([$id]); } header('Location: projects.php'); exit;